reset_confirm_body: "এটি স্থায়ীভাবে সমস্ত স্থানীয় PS5Upload ডেটা মুছে দেয় — সেটিংস, আপনার সংরক্ষিত PS5s, কার্যকলাপ/সারির ইতিহাস, পেলোড ক্যাশে এবং ক্র্যাশ রিপোর্ট । এটি আপনার PS5-এ কিছুই স্পর্শ করে না । অ্যাপটি একটি নতুন অবস্থায় পুনরায় লোড হয় । এটি পূর্বাবস্থায় ফেরানো যাবে না ।",
reset_confirm_action: "সবকিছু মুছে ফেলুন",
crash_reports_hint: "যখন কোনও কিছু ক্র্যাশ বা ত্রুটি ঘটে, তখন আপনার সেটিংসের পাশে একটি বিস্তারিত রিপোর্ট স্বয়ংক্রিয়ভাবে সংরক্ষণ করা হয় । এগুলোকে .zip-এ প্যাকেজ করুন এবং আমাদের ডিসকর্ডে পোস্ট করুন যাতে আমরা ডিবাগ করতে পারি ।",
