connection_step2_browser_unsupported: "ব্রাউজার পাঠানোর জন্য স্থানীয় হেল্পার ফাইল পড়তে পারে না। প্রথমে ডেস্কটপ অ্যাপ বা USB অটোলোডার থেকে হেল্পার লোড করুন — তারপর এই পাতা নিজেই তা শনাক্ত করবে।",
