"pkglib.baseMissing.bodyInLib": "এই {kind} {id}-এর জন্য, যার মূল গেমটি PS5-এ ইনস্টল করা নেই — তবে সেটি আপনার লাইব্রেরিতে আছে। আগে মূল গেমটি ইনস্টল করুন, তারপর এই {kind}। এখন {kind} ইনস্টল করলে তা গৃহীত হবে কিন্তু কার্যকর হবে না।",
