saves_ps4_warning_body: "PS4-ফরম্যাটের সেভডেটা (যেমন ব্যাকওয়ার্ড কম্প্যাটিবিলিটিতে চালানো PS4 গেম) ব্যাকআপ ও পুনরুদ্ধার নির্ভরযোগ্যভাবে নাও চলতে পারে — PS4 এমুলেটর সেভডেটা অভ্যন্তরীণভাবে ক্যাশ করে, আর ফাইল কনসোলে ফিরিয়ে দিলেই তা সবসময় পুনরায় মাউন্ট হয় না। পুনরুদ্ধার করা PS4 সেভ গেমে না দেখা গেলে গেমটি বন্ধ করে আবার চালু করুন, বা কনসোল রিস্টার্ট করুন। এটি একটি জানা সীমাবদ্ধতা এবং ইস্যু #198-এ ট্র্যাক করা হচ্ছে।",
saves_ps4_warning_title: "PS4-ফরম্যাটের সেভডেটা:",
saves_restore_usb: "USB থেকে পুনরুদ্ধার",
saves_restore_usb_all: "সব USB থেকে পুনরুদ্ধার করুন",
saves_restore_usb_all_confirm_body: "এটি প্রতিটি গেমের PS5-এ থাকা বর্তমান সেভডেটা মুছে ফেলে USB-র সর্বশেষ ব্যাকআপ দিয়ে প্রতিস্থাপন করবে। USB ড্রাইভে যেসব গেমের ব্যাকআপ নেই সেগুলো বাদ যাবে। আপলোড বাধাগ্রস্ত হলে স্বয়ংক্রিয় রোলব্যাক নেই।",
