upload_rest_after_hint: "কনসোলের আপলোড সারি শেষ হলে কনসোলকে রেস্ট মোডে যেতে বলুন — রাতভর সারির জন্য সুবিধাজনক। কেবল অন্তত একটি আপলোড সফল হলেই চলে (থামানোর পরে বা সব ব্যর্থ হলে নয়)। ডিফল্টভাবে বন্ধ। কিছু ফার্মওয়্যার স্ট্যান্ডবাই সমর্থন নাও করতে পারে, এবং প্রত্যাখ্যাত হলে আপনাকে জানানো হবে।",
