about_disclaimer_title: "দাবিত্যাগ",
about_disclaimer_purpose: "ps5upload কেবল গবেষণা, শিক্ষা, আন্তঃসঞ্চালনযোগ্যতা এবং হোমব্রু ডেভেলপমেন্টের উদ্দেশ্যে সরবরাহ করা হয়েছে। এটি Sony Interactive Entertainment Inc.-এর সঙ্গে যুক্ত নয়, অনুমোদিত নয় এবং সম্পর্কিতও নয়। “PlayStation” ও “PS5” হলো Sony Interactive Entertainment Inc.-এর ট্রেডমার্ক, এখানে কেবল শনাক্তকরণের জন্য ব্যবহৃত হয়েছে।",
about_disclaimer_piracy: "কেবল আপনার নিজের মালিকানাধীন হার্ডওয়্যার এবং আইনসম্মতভাবে আপনার মালিকানাধীন কনটেন্টের সঙ্গে এটি ব্যবহার করুন। যে সফটওয়্যার ব্যবহারের অধিকার আপনার নেই, তা অনুলিপি, বিতরণ বা চালানোর জন্য এটি ব্যবহার করা যাবে না।",
about_disclaimer_risk: "এই সফটওয়্যারটি “যেমন আছে তেমন” ভিত্তিতে, কোনো প্রকার ওয়ারেন্টি ছাড়াই সরবরাহ করা হয়েছে। পরিবর্তিত কনসোল চালালে তা স্থায়ীভাবে নষ্ট হতে পারে, সেভ ও লাইসেন্স অপুনরুদ্ধারযোগ্যভাবে ধ্বংস হতে পারে এবং আপনার অ্যাকাউন্ট বা কনসোল নিষিদ্ধ হতে পারে। আপনি সম্পূর্ণ নিজ ঝুঁকিতে এটি ব্যবহার করছেন এবং ফলাফলের সম্পূর্ণ দায়িত্ব গ্রহণ করছেন। শুরু করার আগে যা হারানো আপনার পক্ষে সম্ভব নয়, তার ব্যাকআপ নিয়ে রাখুন।",
about_disclaimer_read_full: "সম্পূর্ণ শর্তাবলি পড়ুন",
backup_explain: "কনসোল থেকে ফাইল এই কম্পিউটারে অনুলিপি করে, যাতে পরে সেগুলি ফিরিয়ে দিতে পারেন। নিচ থেকে প্রচলিত কিছু বেছে নিন, অথবা নিজের পথ লিখুন।",
