// --- added v5.4.19: natively-split archive volumes ---
upload_split_pick_entry_title: "এর বদলে \"{name}\" বেছে নিন",
upload_split_pick_entry_body: "এটি একটি বিভক্ত সেটের একটি ভলিউম, পুরো আর্কাইভ নয়। উপরের ফাইলটি বেছে নিন — বাকি ভলিউমগুলো আপনাআপনি পড়া হবে, আলাদা করে আপলোড করার দরকার নেই।",
upload_split_unsupported_title: "এটি একটি বিভক্ত আর্কাইভ ({count}টি ভলিউম) যা ps5upload খুলতে পারে না",
upload_split_unsupported_body: "আপলোড করলে কাঁচা ভলিউমটিই আপনার PS5-তে যাবে, যা সেটি ব্যবহার করতে পারবে না। আগে ভলিউমগুলো একটি আর্কাইভে জোড়া লাগান: 7-Zip বা WinRAR দিয়ে প্রথম ভলিউমটি খুলে এক্সট্র্যাক্ট করুন, তারপর এক্সট্র্যাক্ট করা ফোল্ডার বা তার একটিমাত্র আর্কাইভ আপলোড করুন।",
