"connection_prior_killed_detail": "এর মানে হতে পারে কনসোলের অন্য কোনো payload এটিকে বন্ধ করেছে, সিস্টেমের মেমরি কমে গিয়েছিল, অথবা এটি ক্র্যাশ করেছে। বাগ রিপোর্টের stderr.log জানায় কোনটি ঘটেছে। আপনি যদি অটোলোডার দিয়ে ps5upload লোড করেন, তবে এর বদলে এখান থেকে পাঠিয়ে দেখুন।",
"connection_elfldr_first": "অটোলোডার বা PLDMGR দিয়ে ps5upload লোড করছেন? তালিকায় elfldr সবার আগে রাখুন, ps5upload.elf-এর আগে। elfldr আগে লোড না হলে ps5upload সংযোগ করে কয়েক সেকেন্ডের মধ্যে বিচ্ছিন্ন হয়ে যায়।",
