"games_ready_description": "এই PS5-এ নিবন্ধিত গেম। এখান থেকে চালু, বন্ধ, পরীক্ষা বা আনইনস্টল করুন।",
"games_files_description": "কনসোলের স্টোরেজে পাওয়া গেম ফোল্ডার ও ডিস্ক ইমেজ। এখান থেকে সোর্স ফাইল মাউন্ট, নিবন্ধন, স্থানান্তর বা পরীক্ষা করুন।",
