"update_channel_prerelease_hint": "নতুন রিলিজ প্রকাশ হওয়া মাত্র দেয়, আসল হার্ডওয়্যারে যাচাইয়ের আগেই। শুধু যাচাই করা রিলিজ পেতে এটি বন্ধ রাখুন।",
