"pkglib.fpkgsupport.title": "নকল প্যাকেজ (FPKG) ইনস্টল করছেন?",
"pkglib.fpkgsupport.lead": "কনসোলে নকল-প্যাকেজ সাপোর্ট আগে থেকে লোড থাকলে তবেই PS5 নকল প্যাকেজ ইনস্টল হয়। ইনস্টলের আগে তিনটিই এই ক্রমে লোড করুন:",
"pkglib.fpkgsupport.kstuff": "— PS5 নকল-প্যাকেজ সাপোর্টসহ সংস্করণ",
"pkglib.fpkgsupport.ppr": "— PPR প্লেইনটেক্সট / প্রমাণীকরণ-ছাড়া প্যাচ প্রয়োগ করে",
"pkglib.fpkgsupport.smp": "— ইনস্টল করা টাইটেল নিবন্ধন করে এমন মাউন্ট স্তর",
"pkglib.fpkgsupport.tail": "এগুলো ছাড়া কনসোল ইনস্টল প্রত্যাখ্যান করে, অথবা গ্রহণ করে পরে গেম মাউন্ট করতে পারে না। রিটেল ও ডিবাগ প্যাকেজের এর কোনোটিই লাগে না — আপনি সেটি ইনস্টল করলে এই নোট উপেক্ষা করুন।",
"fpkg_title": "FPKG-তে রূপান্তর",
"fpkg.subtitle": "একটি গেম ফোল্ডার বা মাউন্ট ইমেজকে ইনস্টলযোগ্য প্যাকেজে পরিণত করুন। কাজটি এই মেশিনে চলে, কনসোলে নয়।",
