"fpkg.languageHint": "বেশিরভাগ গেম কনসোলের ভাষা অনুসরণ করে। শুধু সেই গেমের জন্য একটি বেছে নিন যা অন্য ভাষায় সেট করা কনসোলেও ইংরেজিতে থাকে: তখন প্যাকেজ গেমকে জানায় যে সেই ভাষাই ইনস্টল করা। গেমে সেই ভাষা থাকতে হবে।",
