"fpkg.lowSpace": "খালি জায়গা কম: রূপান্তরে আউটপুট ড্রাইভে {need} পর্যন্ত লাগতে পারে, যেখানে আছে {free}।",
"fpkg.about": "একটি গেম ফোল্ডার, অথবা .exfat বা .ffpkg মাউন্ট ইমেজ দেখান। রূপান্তরকারী ট্রি পড়ে, চালানোযোগ্য প্যাকেজের যা লাগে সব আছে কিনা পরীক্ষা করে, এবং আউটপুট ফোল্ডারে ডিবাগ-ফরম্যাটের .pkg লেখে।",
"fpkg.aboutWhere": "রূপান্তর চলে ইঞ্জিন চালানো মেশিনে — এই কম্পিউটার, কোনো Docker হোস্ট বা Android ডিভাইস — কনসোলে নয়। প্যাকেজ ইনস্টল না করা পর্যন্ত কনসোলে কিছুই পৌঁছায় না — এই কম্পিউটার থেকে স্ট্রিম করে, অথবা আগে PS5-এ আপলোড করে।",
"fpkg.aboutSource": "উৎসটি আগে থেকেই ডিক্রিপ্ট করা গেম ট্রি হতে হবে। রিটেল ইনস্টল এখানে খোলা যায় না, আর আপনি সেটি বেছে নিলে নিচের পরীক্ষা তা জানাবে।",
"fpkg.aboutFake": "ফলাফল একটি নকল প্যাকেজ, তাই ইনস্টলের আগে কনসোলে নকল-প্যাকেজ সাপোর্ট লোড থাকতে হবে: kstuff (PS5 নকল-প্যাকেজ সাপোর্টসহ সংস্করণ), a53_ppr_install_fast.elf এবং shadowmountplus.elf, এই ক্রমে। প্যাকেজ ইনস্টল স্ক্রিনেও ইনস্টল বোতামের পাশে একই কথা বলা আছে।",
"fpkg.aboutChecks": "পরীক্ষায় যা দেখা হয়",
"fpkg.checkEboot": "ট্রির মূলে একটি eboot.bin — টাইটেল মডিউল। এটি কাঁচা ELF বা মোড়ানো SELF হতে হবে; রিটেল-স্বাক্ষরিত মডিউল পুনরায় প্যাকেজ করা যায় না।",
"fpkg.checkParam": "sce_sys/param.json থাকতে হবে, আর sce_sys/param.sfo থাকবে না — param.sfo কনসোলের চালু-পথকে PS4-এর পথে পাঠায়।",
"fpkg.checkIcons": "৩৬ অক্ষরের কনটেন্ট আইডি, দুটি আইকন, এবং অধিকার মডিউল sce_sys/about/right.sprx।",
"fpkg.checkDrm": "প্যাকেজের DRM মান স্ট্যান্ডার্ড কিনা। বিনামূল্যের বা আপগ্রেডযোগ্য মান থাকলে কনসোল টাইটেল লক করে; এটি কেবল প্যাকেজে পুনর্লিখিত হয়, আপনার নিজের ফাইল কখনো ছোঁয়া হয় না।",
"payloads_essentials_title": "ps5upload-এর সাথে প্রস্তাবিত",
"payloads_essentials_body": "প্রথমবার কনসোল সেট আপ করলে, এই তিনটি ps5upload যা আশা করে তার বেশিরভাগ পূরণ করে: kstuff-lite (বেশিরভাগ হোমব্রু যে কার্নেল প্যাচের ওপর নির্ভর করে), ShadowMount+ (স্টোরেজ থেকে গেম ইমেজ মাউন্ট) এবং nanoDNS (কনসোলকে Sony-র আপডেট পথ থেকে দূরে রাখে)। তালিকার বাকি সবকিছু ঐচ্ছিক।",
"payloads_tab_shadowmount": "ShadowMount+",
"payloads_tab_nanodns": "nanoDNS",
"payloads_description_shadowmount": "নির্বাচিত PS5-এ ShadowMount+-এর অবস্থা, মাউন্ট করা গেম ইমেজ, কনফিগারেশন ও ডায়াগনস্টিক দেখুন।",
"payloads_description_nanodns": "nanoDNS payload কনফিগার করুন, চলমান সংস্করণ যাচাই করুন, এবং নিরাপদ কনফিগ মাইগ্রেশন প্রয়োগ করুন।",
