"bug_report_open_github": "GitHub ইস্যু খুলুন",
"bug_report_post_hint_v2": "এখন এটি এমন জায়গায় পাঠান যেখানে দেখা হবে: GitHub-এ একটি ইস্যু খুলে .zip সংযুক্ত করুন, অথবা Discord-এর বাগ-রিপোর্ট চ্যানেলে পোস্ট করুন। সমাধান পর্যন্ত যা অনুসরণ করতে হবে তার জন্য GitHub ভালো; এটি পরিচিত সমস্যা কিনা শুধু জানতে চাইলে Discord দ্রুত। যেভাবেই হোক, আপনি কী করছিলেন সংক্ষেপে লিখুন।",
