"pkglib.url.title": "HTTP(S) লিংক থেকে ইনস্টল",
"pkglib.url.help": "এই কম্পিউটার একসাথে কয়েকটি সংযোগে প্যাকেজ ডাউনলোড করে আপনার নেটওয়ার্কে PS5-কে দেয়, তাই স্থানান্তর কনসোলের ধীর একক স্ট্রিমের বদলে আপনার লাইনের গতিতে চলে। কোনো মেশিনেই কিছু রাখা হয় না, তাই ১০০ GB গেমেও খালি জায়গা লাগে না। লিংকটি বাইট রেঞ্জ সমর্থনকারী সরাসরি ডাউনলোড হতে হবে। ইনস্টল শেষ না হওয়া পর্যন্ত এই কম্পিউটার জাগিয়ে রাখুন।",
"pkglib.url.label": "সরাসরি প্যাকেজ URL",
"pkglib.url.install": "লিংক ইনস্টল",
"pkglib.url.confirmTitle": "পরীক্ষামূলক লিংক ইনস্টল শুরু করবেন?",
"pkglib.url.confirmBody": "এই কম্পিউটার লিংক থেকে প্যাকেজ ডাউনলোড করে PS5-কে দেয়, তাই ইনস্টল শেষ না হওয়া পর্যন্ত এটি জাগ্রত ও সংযুক্ত থাকতে হবে। বিদ্যমান টাইটেলের ওপর আবার ইনস্টল করলে Sony-র ইনস্টলার ব্যর্থ হলে সেটি সরে যেতে পারে। শুধু বিশ্বস্ত প্যাকেজ URL ব্যবহার করুন যা ইনস্টল করার অনুমতি আপনার আছে।",
