"library_mount_modal_rw_body": "এভাবে মাউন্ট করলে আপনি ফাইল বদলাতে, DLC যোগ করতে বা ব্যাকপোর্ট প্যাচ প্রয়োগ করতে পারেন — মাউন্ট সম্পাদনার জন্য ফাইল ব্রাউজার ব্যবহার করুন। পরিবর্তন সরাসরি ইমেজ ফাইলে লেখা হয়: ভুল সম্পাদনায় গেম চালু না-ও হতে পারে এবং তা ফেরানো যায় না, তাই গুরুত্বপূর্ণ হলে আগে ইমেজ কপি করুন। PS5 নিজে থেকেও মাউন্ট করা ইমেজে সেভ ডেটা লিখতে পারে।",
