"pkg.patch_loader_not_listening": "এই আপডেট প্রয়োগ করা যায়নি, কারণ আপনার PS5-এর payload লোডার চলছে কিন্তু পোর্ট 9021-এ সংযোগ নিচ্ছে না, তাই প্রয়োজনীয় ইনস্টলার কখনো পৌঁছায়নি এবং কনসোল আপডেটটি দেখেনি। আপনার মূল গেম অক্ষত আছে। আপনার জেলব্রেক পেজ থেকে এটি আবার লোড করুন — যে লোডার প্রক্রিয়া আগে একটি payload দিয়েছে তা সবসময় শুনতে থাকে না। আপডেটটি ইতিমধ্যে আপনার PS5-এ আছে, তাই আবার আপলোড লাগবে না — প্যাকেজ তালিকা থেকে ইনস্টল আবার চেষ্টা করুন। আপনি PS5 থেকেও আপডেট প্রয়োগ করতে পারেন: সেটিংস → সিস্টেম → ডিবাগ সেটিংস → গেম → Package Installer।",
"pkg.reverify_impossible": "PS5 এই ইনস্টল গ্রহণ করেছে, কিন্তু ইনস্টল হওয়া প্যাকেজ চেনার মতো কিছু ps5upload-এর কাছে নেই, তাই এটি নিশ্চিত করতে পারে না। ফলাফলের জন্য PS5-এর বিজ্ঞপ্তি দেখুন। প্রস্তুত করা প্যাকেজ রাখা হয়েছে।",
"pkg.reverify_gave_up": "৩০ মিনিট পরেও নিশ্চিত হয়নি। খুব বড় টাইটেলে আরও সময় লাগতে পারে — PS5-এর বিজ্ঞপ্তি দেখুন, অথবা আবার পরীক্ষা ব্যবহার করুন।",
