volumes_pkg_copies_hint: "এই পছন্দ যা করে: “আপলোড ও ইনস্টল” প্রথমে .pkg ফাইলটি PS5-এ কপি করে, তারপর সেই কপি থেকে ইনস্টল করে। এটি শুধু ঠিক করে কোন ড্রাইভে সেই কপিগুলো থাকবে। গেম কোথায় ইনস্টল হবে তা বদলায় না (PS5 নিজের স্টোরেজ সেটিংসে তা ঠিক করে), আর “স্ট্রিম ও ইনস্টল” কোনো কপিই রাখে না। নির্বাচিত ড্রাইভ সংযুক্ত না থাকলে কপি ইন্টারনাল স্টোরেজে যায়।",
