"arcpkg.choose": "আর্কাইভ বেছে নিন…",
"arcpkg.help": "এমন .zip, .7z বা .rar-এর জন্য, যার যেকোনো ফোল্ডারে এক বা একাধিক .pkg ফাইল আছে। শুধু প্যাকেজগুলো খোলা হয়, সরাসরি PS5-এ (এই কম্পিউটারে কিছুই বের করা হয় না), তারপর একটি একটি করে ইনস্টল হয়: আগে মূল গেম, তারপর তার আপডেট, তারপর DLC। একাধিক অংশের RAR (.part1.rar, .part2.rar…) সমর্থিত: প্রথম অংশটি বেছে নিন এবং বাকিগুলো তার পাশে রাখুন। RAR-এর পাসওয়ার্ড লাগলে চাওয়া হয়; পাসওয়ার্ডযুক্ত ZIP ও 7z সমর্থিত নয়।",
"arcpkg.keepsRunning": "আপনি অন্য স্ক্রিন খুললেও এটি চলতে থাকে, এবং «কাজ»-এও দেখা যায়।",
"arcpkg.notArchive": "ফাইলটি .zip, .7z বা .rar আর্কাইভ নয়।",
"arcpkg.pick": "একটি আর্কাইভ বেছে নিন",
"arcpkg.title": "আর্কাইভ থেকে প্যাকেজ ইনস্টল করুন",
"install.library.title": "PS5-এ প্যাকেজের কপি",
"install.stream.file.help": "একটি .pkg বা .fpkg বেছে নিন, অথবা এই উইন্ডোর যেকোনো জায়গায় ছেড়ে দিন। ইনস্টল শেষ না হওয়া পর্যন্ত অ্যাপ খোলা রাখুন; অগ্রগতি ওপরের সারিতে এবং «কাজ»-এ দেখা যায়।",
"install.stream.file.title": "একটি প্যাকেজ ফাইল ইনস্টল করুন",
"install.tab.stream.lead": "PS5 সরাসরি এই কম্পিউটার থেকে বা একটি লিংক থেকে ইনস্টল করে। আগে PS5-এ কোনো কপি রাখা হয় না, তাই সেখানে ফাঁকা জায়গা লাগে না, এবং এটিই ইনস্টলের সবচেয়ে নির্ভরযোগ্য উপায়।",
"install.tab.upload.lead": "প্যাকেজটি আগে PS5-এ কপি হয়, তারপর সেই কপি থেকে ইনস্টল হয়। PS5 এই কম্পিউটারে পৌঁছাতে না পারলে (স্ট্রিম নেটওয়ার্ক ত্রুটিতে ব্যর্থ হয়), অথবা প্যাকেজ PS5-এ রেখে পরে এই কম্পিউটার ছাড়াই আবার ইনস্টল করতে চাইলে এটি ব্যবহার করুন।",
"install.upload.file.browser": "এখান থেকে PS5-এ প্যাকেজ কপি করতে ডেস্কটপ অ্যাপ লাগে। ওয়েব UI-তে «স্ট্রিম ও ইনস্টল» ব্যবহার করুন, অথবা নিচে আগে থেকেই PS5-এ থাকা প্যাকেজ ইনস্টল করুন।",
"install.upload.file.help": "একটি .pkg বা .fpkg বেছে নিন। কপির জন্য PS5-এ পুরো প্যাকেজের সমান ফাঁকা জায়গা লাগে, এবং আপনি মুছে না ফেলা পর্যন্ত এটি নিচের তালিকায় থাকে।",
"install.upload.file.title": "প্যাকেজ PS5-এ কপি করে ইনস্টল করুন",
"linkcard.confirm.direct": "PS5 নিজেই লিংক থেকে প্যাকেজ ডাউনলোড করে ইনস্টল করে। শুরু হওয়ার পর এই কম্পিউটারের দরকার নেই, এবং অগ্রগতি এখানে নয়, PS5-এ (ডাউনলোড) দেখা যায়। PS5 লিংকে পৌঁছাতে না পারলে অ্যাপ সেটি এই কম্পিউটারের মাধ্যমে পাঠায়। ইনস্টল থাকা গেমের ওপর আবার ইনস্টল করলে, Sony-র ইনস্টলার ব্যর্থ হলে সেই গেম মুছে যেতে পারে। শুধু সেই প্যাকেজের লিংক ব্যবহার করুন যেগুলো আপনি বিশ্বাস করেন এবং ইনস্টল করার অধিকার রাখেন।",
"linkcard.confirm.download": "এই কম্পিউটার আগে পুরো প্যাকেজ ডিস্কে সংরক্ষণ করে, তারপর PS5-এ ইনস্টল করে। দুটি ধাপ শেষ না হওয়া পর্যন্ত এটি চালু থাকতে হবে, এবং প্যাকেজের জন্য ফাঁকা জায়গা লাগে। ইনস্টল থাকা গেমের ওপর আবার ইনস্টল করলে, Sony-র ইনস্টলার ব্যর্থ হলে সেই গেম মুছে যেতে পারে। শুধু সেই প্যাকেজের লিংক ব্যবহার করুন যেগুলো আপনি বিশ্বাস করেন এবং ইনস্টল করার অধিকার রাখেন।",
"linkcard.confirm.stream": "এই কম্পিউটার প্যাকেজ ডাউনলোড করে সঙ্গে সঙ্গে PS5-কে দিয়ে দেয়, তাই ইনস্টল শেষ না হওয়া পর্যন্ত এটি চালু ও সংযুক্ত থাকতে হবে। ডিস্কে কিছুই সংরক্ষিত হয় না। ইনস্টল থাকা গেমের ওপর আবার ইনস্টল করলে, Sony-র ইনস্টলার ব্যর্থ হলে সেই গেম মুছে যেতে পারে। শুধু সেই প্যাকেজের লিংক ব্যবহার করুন যেগুলো আপনি বিশ্বাস করেন এবং ইনস্টল করার অধিকার রাখেন।",
