"collection.permanent_delete_hint": "এই ইঞ্জিনে কোনো ট্র্যাশ নেই (Docker বা ডেস্কটপ ছাড়া সার্ভার)। এটি চালু থাকলে সংগ্রহ থেকে কপি মোছা যায়: সেটি চিরতরে চলে যায়, এবং প্রতিবার আপনি নিশ্চিত করেন।",
"collection.trash_unavailable_v2": "এই ইঞ্জিনে কোনো ট্র্যাশ নেই। এখান থেকে কপি মুছতে, সংগ্রহ → ফোল্ডার-এ \"কপি চিরতরে মোছার অনুমতি দিন\" চালু করুন।",
"pkg.sony_80b21104": "PS5 এই প্যাকেজটি নেয়নি (0x80B21104)। এই কনসোলে অন্য প্যাকেজ ইনস্টল হলে সমস্যা এই ফাইলে: বেশিরভাগ সময় নতুন কোনো গেমের প্যাকেজ, যা এমন টুলে তৈরি যা এই কনসোলের ফার্মওয়্যার বোঝে না, অথবা এমন প্যাকেজ যা নকল-স্বাক্ষরিত (FPKG) বিল্ড নয়। আপনার ফার্মওয়্যারের জন্য তৈরি প্যাকেজ (ব্যাকপোর্ট) ব্যবহার করুন, অথবা ইনস্টলার ছাড়া গেমটি ইনস্টল করুন: আপলোড দিয়ে এর গেম ফোল্ডার, বা ShadowMount+-এর জন্য গেম ইমেজ (.exfat বা .ffpfsc) কপি করুন।",
"fpkg.imageQueued": "আপলোড সারিতে আছে: পরের দফায় PS5-এ ShadowMount+ যে ফোল্ডার দেখে সেখানে যাবে।",
