upload_as_image_desc: "হাজার হাজার ফাইলের বদলে একটি ইমেজ ফাইল যা ShadowMount+ মাউন্ট করে: পাঠাতে অনেক দ্রুত, আর কম্প্রেস করলে PS5-এ কম জায়গা নেয়। ইমেজটি প্রথমে এই কম্পিউটারে তৈরি হয় (এখানে জায়গা লাগে), তারপর নিচের ফোল্ডারে আপলোড হয়; অগ্রগতি রূপান্তরে দেখা যায়।",
